    const visible = visibleNav(
      SETTINGS_NAV,
      makeActor({ role: "admin" }),
90→      flagsFor("enterprise", "admin"),
    );
    expect(keysOf(visible)).toContain("settings.flags");
    expect(keysOf(visible)).not.toContain("settings.billing");
  });

